hooks.command:
f=$(python3 -c 'import json,sys
try:
    d=json.load(sys.stdin)
    print(d.get("tool_input",{}).get("file_path",""))
except Exception:
    print("")' 2>/dev/null); case "$f" in *.sh|*/bin/dvd-auto|*/bin/dvd-shrink) bash -n "$f" && command -v shellcheck >/dev/null 2>&1 && shellcheck --severity=warning "$f" ;; *) exit 0 ;; esac
